from typing import List

class Solution:
    def partitionLabels(self, s: str) -> List[int]:
        result = []
        start = 0
        while start < len(s):
            end = start
            changed = True
            while changed:
                changed = False
                for i in range(start, end + 1):
                    last = s.rfind(s[i])
                    if last > end:
                        end = last
                        changed = True
            result.append(end - start + 1)
            start = end + 1
        return result

